<script setup lang="ts">
import { headingText } from '@/utils/reviewPresentation'
import { computed } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
const store = useLessonReviewStore()
const nodes = computed(() => store.data?.graph.nodes || [])
const positions = computed(() => new Map(nodes.value.map((node, i) => [node.id, { x: 88 + (i % 5) * 178, y: 64 + Math.floor(i / 5) * 106 }])))
const height = computed(() => Math.max(220, Math.ceil(nodes.value.length / 5) * 106 + 30))
const relations = computed(() => store.data?.graph.edges.filter(e => !store.selectedNodeId || e.source === store.selectedNodeId || e.target === store.selectedNodeId) || [])
function nodeName(id: string) { return nodes.value.find(node => node.id === id)?.label || id }
function statusName(status: string) { return ({ source_extracted: 'Source-extracted · Unverified', model_proposed: 'Model-proposed · Unverified', teacher_confirmed: 'Teacher confirmed' } as Record<string, string>)[status] || status || 'State not provided' }
</script>
<template>
  <section id="knowledge" class="panel lesson-graph">
    <div class="panel-heading"><div><h2>Connect lesson concepts</h2><p>Concepts and relationships extracted from this lesson. Each item links back to its source</p></div><span class="tag">{{ nodes.length }} Nodes · {{ store.data?.graph.edges.length }} Relationships</span></div>
    <div v-if="nodes.length" class="graph-canvas"><svg :viewBox="`0 0 900 ${height}`" :style="{ minHeight: '220px' }" role="group" aria-label="Knowledge evidence graph for this lesson"><defs><marker id="review-edge-arrow" viewBox="0 0 10 10" refX="22" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#acc6ef" /></marker></defs><g class="graph-edges"><line v-for="edge in store.data?.graph.edges" :key="edge.id" :x1="positions.get(edge.source)?.x" :y1="positions.get(edge.source)?.y" :x2="positions.get(edge.target)?.x" :y2="positions.get(edge.target)?.y" :class="{ connected: edge.source === store.selectedNodeId || edge.target === store.selectedNodeId }" marker-end="url(#review-edge-arrow)"><title>{{ nodeName(edge.source) }} · {{ edge.label }} · {{ nodeName(edge.target) }}</title></line></g><g v-for="node in nodes" :key="node.id" :transform="`translate(${positions.get(node.id)?.x},${positions.get(node.id)?.y})`" class="graph-node" :class="{ selected: store.selectedNodeId === node.id, current: store.currentConceptIds.includes(node.id) }" tabindex="0" role="button" :aria-label="`Concept node ${node.label}. ${node.properties.source_refs.length} sources. Select to seek`" @click="store.selectNode(node.id)" @keydown.enter="store.selectNode(node.id)" @keydown.space.prevent="store.selectNode(node.id)"><circle class="node-halo" r="27" /><circle class="node-dot" r="17" /><text y="44" text-anchor="middle">{{ node.label.length > 12 ? node.label.slice(0, 12) + '…' : node.label }}</text><title>{{ node.label }} · {{ statusName(node.properties.status) }}</title></g></svg></div>
    <div v-else class="empty-state">No concepts or relationships are available for this lesson. Graphs from other lessons are not used to fill gaps.</div>
    <div class="graph-caption"><span><i></i>Darker nodes are linked to the current segment</span><span>Node size does not indicate mastery or activity</span></div>
    <div v-if="store.selectedNode" class="concept-evidence"><div class="concept-evidence-heading"><div><span class="eyebrow">CONCEPT EVIDENCE</span><h3>{{ headingText(store.selectedNode.label) }}</h3></div><span class="tag sand">{{ statusName(store.selectedNode.properties.status) }}</span><button class="clear-concept" @click="store.selectedNodeId = ''">Clear selection</button></div><p>Preserved separately {{ store.selectedIntervals.length }} timed evidence items; Gaps between observations are not attributed to the concept.</p><div class="concept-intervals"><button v-for="interval in store.selectedIntervals" :key="interval.id" @click="store.seek(interval.start_sec)"><span class="mono">{{ formatReviewTime(interval.start_sec) }}–{{ formatReviewTime(interval.end_sec) }}</span><strong>{{ interval.id }}</strong><p>{{ interval.text }}</p></button><p v-if="!store.selectedIntervals.length" class="empty-state">This concept has no resolvable timed evidence. Cannot locate this yet.</p></div></div>
    <div v-if="relations.length" class="graph-relations"><h3>{{ store.selectedNode ? 'Relationships involving the selected concept' : 'Lesson relationships and sources' }}</h3><div v-for="edge in relations" :key="edge.id" class="graph-relation"><p><button @click="store.selectNode(edge.source)">{{ nodeName(edge.source) }}</button><span>{{ edge.label }}</span><button @click="store.selectNode(edge.target)">{{ nodeName(edge.target) }}</button></p><div><button v-for="id in edge.properties.source_refs" :key="id" class="evidence-link" :disabled="!store.evidence(id)" :title="store.evidence(id)?.text || 'No resolvable source'" @click="store.jumpToEvidence(id)">{{ id }}<span v-if="store.evidence(id)"> · {{ formatReviewTime(store.evidence(id)!.start_sec) }}</span></button></div></div></div>
    <p class="graph-footnote">Content links describe relationships between lesson concepts; They do not establish validated prerequisites or student knowledge mastery.</p>
  </section>
</template>
