ne-height:1.8;margin-top:6px}.graph-relations{padding:4px 22px;max-height:310px;overflow:auto}.graph-relations h3{font-size:11px;font-weight:500;color:#5a769c;margin-bottom:5px}.graph-relation{padding:11px 0;border-bottom:1px solid #dde8f8}.graph-relation>p{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.graph-relation>p button{background:none;padding:0;color:#4e698f;font-size:11px}.graph-relation>p span{font-size:9px;color:#607ca4}.graph-relation>div{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.evidence-link{background:#e2ecfa;color:#537098;padding:4px 6px;border-radius:4px;font-size:8px}.evidence-link:hover{background:#ccddf5}.graph-footnote{font-size:9px;line-height:1.8;padding:14px 22px 20px;color:#5d7ca7}@media(max-width:550px){.graph-caption{font-size:8px;padding:12px 15px}.concept-evidence{margin-left:14px;margin-right:14px}.graph-relations{padding-left:17px;padding-right:17px}}
